package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class KeyedObjects2D_removeRow_TriageGen0Test {

    private KeyedObjects2D keyedObjects2D;

    @Before
    public void setUp() {
        keyedObjects2D = new KeyedObjects2D();
    }

    @Test
    public void testRemoveRow_ExistingRow() {
        // Arrange
        String rowKey1 = "Row1";
        String rowKey2 = "Row2";
        String colKey = "Col1";
        keyedObjects2D.addObject("Data1", rowKey1, colKey);
        keyedObjects2D.addObject("Data2", rowKey2, colKey);

        int initialRowCount = keyedObjects2D.getRowCount();
        assertEquals(2, initialRowCount);

        // Act
        keyedObjects2D.removeRow(rowKey1);

        // Assert
        assertEquals(1, keyedObjects2D.getRowCount());
        assertEquals(rowKey2, keyedObjects2D.getRowKey(0));
        assertNull(keyedObjects2D.getObject(rowKey1, colKey));
    }








}

